def calculate(a, op, b):
    if op == "+":
        return a + b
    elif op == "-":
        return a - b
    elif op == "*":
        return a * b
    elif op == "/":
        return a / b
    else:
        return None

while True:
    choice = input("a op b (or q): ")
    if choice == "q":
        break
    a, op, b = choice.split()
    print(calculate(float(a), op, float(b)))

ops = {"+": lambda a, b: a + b, "*": lambda a, b: a * b}
print(ops["+"](2, 3))
print(ops["*"](4, 5))

